public class BookInventory {private int copiesTotal,copiesAvailable;BookInventory(int n){if(n<=0)throw new IllegalArgumentException();copiesTotal=copiesAvailable=n;}void checkOut(){if(copiesAvailable>0)copiesAvailable--;}void checkIn(){if(copiesAvailable<copiesTotal)copiesAvailable++;}int getCopiesAvailable(){return copiesAvailable;}public static void main(String[]a){BookInventory b=new BookInventory(2);b.checkOut();System.out.println(b.getCopiesAvailable());}}
